export function taskLabel(name: string, completed: boolean): string {
    return (completed ? '[x] ' : '[ ] ') + name;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

test('completed task receives [x] prefix', () => {
    assert.equal(taskLabel('draft', true), '[x] draft');
    assert.equal(taskLabel('ship release', true), '[x] ship release');
});

test('incomplete task receives [ ] prefix', () => {
    assert.equal(taskLabel('draft', false), '[ ] draft');
    assert.equal(taskLabel('pending review', false), '[ ] pending review');
});

test('preserves the supplied name exactly', () => {
    assert.equal(taskLabel('', true), '[x] ');
    assert.equal(taskLabel('', false), '[ ] ');
    assert.equal(taskLabel('   spaces   ', true), '[x]    spaces   ');
    assert.equal(taskLabel('task [with] brackets and : symbols!', true), '[x] task [with] brackets and : symbols!');
});
